function loop()
 local kind = luxio_get_color_type()
 if kind == "RGBCCT" then luxio_fill(0, 0, 0, 0, 180, 75)
 elseif kind == "RGBW" then luxio_fill(0, 0, 0, 255)
 else luxio_fill(255, 190, 105) end
end

local waves = {{offset = 0.5}, {offset = 0.5}, {positive = true, offset = -1}}
function loop()
 luxio_render_waves(waves, {
  {offset = 200, multiply = 2, {wave = 1, gain = 200}},
  {{wave = 1, gain = 255, power = 3}},
  {{wave = 3, gain = 255, power = 2}}})
end

function loop()
 luxio_render_waves({{offset = 0.5, {amplitude = 0.25, phase = 0.3, step = -0.2}, {amplitude = 0.1, phase = -0.7, step = 0.4}}}, {{{wave = 1}}, {{wave = 1, gain = 100, power = 8}}, {offset = -10}})
end

function loop()
 local channels = {}
 local kind = luxio_get_color_type()
 if kind == "RGBCCT" then channels[5] = {{wave = 1, gain = 180}}; channels[6] = {{wave = 1, gain = 75}}
 elseif kind == "RGBW" then channels[4] = {{wave = 1}}
 else channels = {{{wave = 1}}, {{wave = 1, gain = 190}}, {{wave = 1, gain = 105}}} end
 luxio_render_waves({{offset = 1}}, channels)
end
